// Executed by the test bundle generated by prepare_rotation_test.py.
// Uses real Photoshop text layers and the actual importer, not mocked bounds.
(function () {
    var api = LabelPlus.rotationTest;
    var oldUnits = app.preferences.rulerUnits;
    var oldDialogs = app.displayDialogs;
    app.preferences.rulerUnits = Units.PIXELS;
    app.displayDialogs = DialogModes.NO;
    var results = [], doc = null;
    var root = File($.fileName).parent;
    var s2t = function (s) { return app.stringIDToTypeID(s); };

    // Independent measurement: transform all four box corners and average them.
    // Use the descriptor's percent-based origin rather than textItem.position.
    function measure(layer, document) {
        document.activeLayer = layer;
        var ref = new ActionReference();
        ref.putProperty(s2t('property'), s2t('textKey'));
        ref.putEnumerated(s2t('layer'), s2t('ordinal'), s2t('targetEnum'));
        var text = app.executeActionGet(ref).getObjectValue(s2t('textKey'));
        var box = text.getObjectValue(s2t('boundingBox'));
        var origin = text.getObjectValue(s2t('textClickPoint'));
        var ox = origin.getUnitDoubleValue(s2t('horizontal')) * document.width.as('px') / 100;
        var oy = origin.getUnitDoubleValue(s2t('vertical')) * document.height.as('px') / 100;
        var t = text.hasKey(s2t('transform')) ? text.getObjectValue(s2t('transform')) : null;
        var xx = t ? t.getDouble(s2t('xx')) : 1, xy = t ? t.getDouble(s2t('xy')) : 0;
        var yx = t ? t.getDouble(s2t('yx')) : 0, yy = t ? t.getDouble(s2t('yy')) : 1;
        var scale = document.resolution / 72;
        var l = box.getUnitDoubleValue(s2t('left')) * scale, r = box.getUnitDoubleValue(s2t('right')) * scale;
        var top = box.getUnitDoubleValue(s2t('top')) * scale, bottom = box.getUnitDoubleValue(s2t('bottom')) * scale;
        var local = [[l, top], [r, top], [r, bottom], [l, bottom]], corners = [], cx = 0, cy = 0;
        for (var i = 0; i < local.length; i++) {
            var x = ox + xx * local[i][0] + yx * local[i][1];
            var y = oy + xy * local[i][0] + yy * local[i][1];
            corners.push([x, y]); cx += x; cy += y;
        }
        return { x: cx / 4, y: cy / 4, corners: corners };
    }
    function distance(p) { return Math.sqrt(Math.pow(p.x - 400, 2) + Math.pow(p.y - 400, 2)); }
    function drawPreview(layer, filename) {
        var measured = measure(layer, doc);
        var guide = doc.artLayers.add(); guide.name = 'Blue: text box / Red: target (400,400)';
        var blue = new SolidColor(); blue.rgb.hexValue = '007AFF';
        doc.selection.select(measured.corners); doc.selection.stroke(blue, 2); doc.selection.deselect();
        var red = new SolidColor(); red.rgb.hexValue = 'FF3030';
        doc.selection.select([[380,399],[420,399],[420,401],[380,401]]); doc.selection.fill(red); doc.selection.deselect();
        doc.selection.select([[399,380],[401,380],[401,420],[399,420]]); doc.selection.fill(red); doc.selection.deselect();
        var png = new PNGSaveOptions();
        doc.saveAs(new File(root.fsName + '/' + filename), png, true, Extension.LOWERCASE);
        guide.remove();
    }
    try {
        var ppis = [72, 300], angles = [0, 15, 30, -30, 45, 90];
        for (var p = 0; p < ppis.length; p++) {
            for (var direction = 0; direction < 2; direction++) {
                for (var a = 0; a < angles.length; a++) {
                    doc = app.documents.add(800, 800, ppis[p], 'Rotation test', NewDocumentMode.RGB, DocumentFill.WHITE);
                    var opts = new LabelPlus.CustomOptions();
                    opts.docTemplate = LabelPlus.OptionDocTemplate.No;
                    opts.centerAlign = true; opts.useMeoFontSize = true;
                    opts.tsumeChars = ''; opts.verticalRomanChars = ''; opts.tateChuYokoPatterns = '';
                    opts.groupSelected = ['translation']; opts.noLayerGroup = true;
                    api.setOptions(opts);
                    var workspace = { doc: doc, groups: { translation: {} }, pendingDelLayerList: [] };
                    var label = { x: 0.5, y: 0.5, group: 'translation', contents: 'AAAAAA\rA',
                        fontSize: ppis[p] === 72 ? 48 : 12, font: 'ArialMT', color: '#111111',
                        orientation: direction ? 'vertical' : 'horizontal', rotation: angles[a] };
                    api.importImage({ ws: workspace, labels: [label] });
                    var layer = doc.activeLayer;
                    var fixed = measure(layer, doc);
                    if (ppis[p] === 72 && direction === 0 && angles[a] === 30) drawPreview(layer, 'rotation-fixed.png');
                    // Reproduce the old correction on the same rendered text for comparison.
                    var b = layer.bounds;
                    layer.translate(UnitValue(400 - (b[0].as('px') + b[2].as('px')) / 2, 'px'),
                                    UnitValue(400 - (b[1].as('px') + b[3].as('px')) / 2, 'px'));
                    var previous = measure(layer, doc);
                    if (ppis[p] === 72 && direction === 0 && angles[a] === 30) drawPreview(layer, 'rotation-before.png');
                    results.push({ ppi: ppis[p], direction: direction ? 'vertical' : 'horizontal', rotation: angles[a],
                        before: { x: previous.x, y: previous.y, error: distance(previous) },
                        after: { x: fixed.x, y: fixed.y, error: distance(fixed) }, passed: distance(fixed) < 0.1 });
                    doc.close(SaveOptions.DONOTSAVECHANGES); doc = null;
                }
            }
        }
    } catch(e) { results.push({ error: e.toString(), line: e.line }); }
    finally {
        if (doc) doc.close(SaveOptions.DONOTSAVECHANGES);
        app.preferences.rulerUnits = oldUnits; app.displayDialogs = oldDialogs;
        var report = new File(root.fsName + '/rotation-results.json');
        report.encoding = 'UTF-8'; report.open('w'); report.write(jamJSON.stringify(results, '  ')); report.close();
    }
}());
